-- Seasonal already exists; associate all November 2 pages without duplicating links.
INSERT OR IGNORE INTO page_themes (page_id, theme_id) SELECT page.id, theme.id FROM coloring_pages AS page CROSS JOIN themes AS theme WHERE page.slug LIKE 'november-2-%' AND theme.slug = 'seasonal';
